import { useEffect, useMemo, useRef, useState } from "react";
import {
  AlertTriangle,
  ArrowRightLeft,
  Box,
  BookmarkPlus,
  ChevronDown,
  ChevronRight,
  ClipboardCopy,
  CopyPlus,
  Layers3,
  Link2,
  LockKeyhole,
  Pencil,
  Plus,
  RefreshCw,
  Search,
  Trash2,
  Unlink,
} from "lucide-react";
import CreatePartGroupModal from "./CreatePartGroupModal";
import BuilderPartEditWarningModal from "./BuilderPartEditWarningModal";
import DetachedPartOverrideModal from "./DetachedPartOverrideModal";
import MasterPartPickerModal from "@/components/estimator/parts/MasterPartPickerModal";
import { base44 } from "@/api/base44Client";
import { staffEntities } from "@/components/staff/staffEntities";
import { detachBuilderPartOverride, updateDetachedPartOverride } from "@/components/estimator/builder/partSync";
import { CopyBomButton } from "@/components/importer/ImportExportButtons";
import { addCatalogPartToProduct, removeManualProductPart, switchManualProductPart, updateManualProductPart } from "@/components/estimator/parts/customProductService";
import { typeDetails } from "@/components/estimator/parts/partCatalog";
import { money } from "@/components/estimator/aioPricing";
import { copyPartGroupToClipboard, copyPartToClipboard } from "@/components/estimator/products/clipboardService";
import { clonePartGroupInProduct, createPartGroupInProduct, dissolvePartGroup, moveIndependentPartGroup, renamePartGroup } from "@/components/estimator/parts/partGroupService";
import { expectedBuilderEntityFields, replaceBuilderEntityFieldsIfUnchanged } from "@/components/estimator/builder/builderEntityPersistence";
import MovePartGroupModal from "./MovePartGroupModal";
import SavePartTemplateModal from "@/components/estimator/parts/SavePartTemplateModal";
import PartLibraryPickerModal from "@/components/estimator/parts/PartLibraryPickerModal";
import VendorCostBadge from "@/components/estimator/VendorCostBadge";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";

const num = (value, fallback = 0) =>
  Number.isFinite(Number(value)) ? Number(value) : fallback;

// (#407) Large part lists render in chunks of PART_ROW_PAGE so a 300-part
// product doesn't mount hundreds of PartRow trees at once. A "Show more"
// control reveals the next chunk; searching bypasses the window so every
// match stays reachable.
const PART_ROW_PAGE = 100;

const typeLabel = (part) =>
  String(part?.part_type || "part")
    .replaceAll("_", " ")
    .replace(/\b\w/g, (char) => char.toUpperCase());

const priceStateMeta = (part) => {
  if (["detached", "reattach_available"].includes(part.inventory_link_state) || part.price_state === "detached") {
    return { label: "Detached", className: "bg-amber-50 text-amber-700 border-amber-200", icon: Unlink };
  }
  if (part.price_state === "changed") {
    return { label: "Price updated", className: "bg-amber-50 text-amber-700 border-amber-200", icon: AlertTriangle };
  }
  if (part.price_state === "legacy_frozen") {
    return { label: "Frozen legacy price", className: "bg-slate-100 text-slate-600 border-slate-200", icon: LockKeyhole };
  }
  return { label: "Price current", className: "bg-green-50 text-green-700 border-green-200", icon: Link2 };
};

function PartRow({ part, index, selectionMode = false, selected = false, onSelect, onChanged, onEditBuilder, estimateId, expectedEstimateUpdatedAt = "", readOnly = false }) {
  const [open, setOpen] = useState(false);
  const [warningOpen, setWarningOpen] = useState(false);
  const [overrideOpen, setOverrideOpen] = useState(false);
  const [switchOpen, setSwitchOpen] = useState(false);
  const [copying, setCopying] = useState(false);
  const [copied, setCopied] = useState(false);
  const [saveLibraryOpen, setSaveLibraryOpen] = useState(false);
  const frozen = num(part.frozen_extended_cost);
  const current = num(part.current_extended_cost, frozen);
  const differs = Math.abs(current - frozen) > 0.005;
  const meta = priceStateMeta(part);
  const StatusIcon = meta.icon;
  const isManual = part.builder_sync_state === "manual";
  const isManualAddon = part.builder_sync_state === "manual_addon";
  const isDetachedOverride = part.builder_sync_state === "detached_override";
  const isDirectlyEditable = isManual || isManualAddon;
  const isIndependent = isDirectlyEditable || isDetachedOverride;
  const inventoryDetails = typeDetails(part.inventory_entity, part.frozen_inventory_snapshot || {}, part.detail_overrides || {});

  return (
    <div className="border border-gray-200 rounded-sm bg-white overflow-hidden">
      <div className="w-full min-h-[42px] px-3 py-2 flex items-center gap-2 text-left hover:bg-gray-50">
        {selectionMode && (
          <input
            type="checkbox"
            checked={selected}
            onChange={(event) => onSelect?.(part.id, event.target.checked)}
            className="h-4 w-4 rounded border-gray-300 accent-lime-500 flex-shrink-0"
            aria-label={`Select ${part.part_name || "Part"}`}
          />
        )}
        <button
          type="button"
          onClick={() => setOpen((value) => !value)}
          aria-expanded={open}
          className="flex-1 min-w-0 flex items-center gap-2 text-left"
        >
        {open ? <ChevronDown className="w-3.5 h-3.5 text-gray-500" aria-hidden="true" /> : <ChevronRight className="w-3.5 h-3.5 text-gray-500" aria-hidden="true" />}
        <Box className="w-3.5 h-3.5 text-gray-400" aria-hidden="true" />
        <span className="text-[9px] font-bold tracking-wider text-gray-400 w-[52px] flex-shrink-0">PART {String(index + 1).padStart(2, "0")}</span>
        <span className="text-[12px] font-semibold text-gray-900 truncate flex-1">{part.client_label || part.part_name || "Part"}</span>
        <span className="hidden md:inline text-[10px] text-gray-500 px-2 py-0.5 rounded bg-gray-100">{typeLabel(part)}</span>
        <span className={`hidden sm:inline-flex items-center gap-1 text-[9px] px-2 py-0.5 rounded-full border ${meta.className}`}>
          <StatusIcon className="w-3 h-3" aria-hidden="true" /> {meta.label}
        </span>
          <div className="text-right w-[92px] flex-shrink-0">
            <div className="text-[11px] font-bold text-gray-800">{money(frozen)}</div>
            {differs && <div className="text-[9px] text-amber-600">current {money(current)}</div>}
          </div>
        </button>
      </div>

      {/* F-21: vended-part vendor cost/markup strip — renders only when the
          part resolves as vended; Edit reuses the row's own edit path. */}
      <VendorCostBadge
        part={part}
        onEdit={readOnly ? null : () => (isIndependent ? setOverrideOpen(true) : setWarningOpen(true))}
      />

      {open && (
        <div className="border-t border-gray-200 bg-gray-50 px-3 py-3">
          <div className="flex items-center justify-between gap-2 mb-3">
            <div className="text-[10px] text-gray-500">
              {isManual ? "Custom Product Part — edit directly or keep tracking its Master Inventory price." : isManualAddon ? "Independent add-on Part — not controlled by this Builder and safe from Builder recalculation." : isDetachedOverride ? "Independent override — Builder synchronization is disabled." : "Builder-linked Part — edit through the Builder or detach it first."}
              {isDetachedOverride && part.builder_detached_at && (
                <div className="text-[10px] text-amber-700 mt-0.5">
                  Detached {new Date(part.builder_detached_at).toLocaleString()}{part.builder_detached_by ? ` by ${part.builder_detached_by}` : ""}{part.builder_detached_reason ? ` — ${part.builder_detached_reason}` : ""}
                </div>
              )}
            </div>
            <div className="flex items-center gap-1.5">
              {estimateId && (
                <button
                  type="button"
                  disabled={copying}
                  onClick={async () => {
                    setCopying(true);
                    try {
                      await copyPartToClipboard({ estimateId, builderProductId: part.builder_product_id, part });
                      setCopied(true);
                      setTimeout(() => setCopied(false), 1500);
                    } catch (error) {
                      window.alert(error?.message || "Part could not be copied to the estimator clipboard.");
                    } finally {
                      setCopying(false);
                    }
                  }}
                  className="h-[28px] px-2.5 rounded border border-gray-300 bg-white text-[11px] font-semibold text-gray-700 hover:bg-gray-100 inline-flex items-center gap-1 disabled:opacity-50"
                  title="Copy Part to 30-day Clipboard"
                  aria-label={`Copy ${part.part_name || "Part"} to 30-day clipboard`}
                ><ClipboardCopy className="w-3 h-3" aria-hidden="true" /> {copied ? "Copied" : "Copy"}</button>
              )}
              <button type="button" onClick={() => setSaveLibraryOpen(true)} className="h-[28px] px-2.5 rounded border border-violet-200 bg-white text-[11px] font-semibold text-violet-700 hover:bg-violet-50 inline-flex items-center gap-1" title="Save Part permanently to Part Library" aria-label={`Save ${part.part_name || "Part"} permanently to Part Library`}><BookmarkPlus className="w-3 h-3" aria-hidden="true" /> Save</button>
              {!readOnly && isDirectlyEditable && (
                <button type="button" onClick={() => setSwitchOpen(true)} className="h-[28px] px-3 rounded border border-gray-300 bg-white text-[11px] font-semibold text-gray-700 hover:bg-gray-100 inline-flex items-center gap-1"><RefreshCw className="w-3 h-3" aria-hidden="true" /> Switch Part</button>
              )}
              {!readOnly && (
                <button
                  type="button"
                  onClick={() => isIndependent ? setOverrideOpen(true) : setWarningOpen(true)}
                  className="h-[28px] px-3 rounded border border-gray-300 bg-white text-[11px] font-semibold text-gray-700 hover:bg-gray-100"
                >
                  {isDetachedOverride ? "Edit Override" : "Edit Part"}
                </button>
              )}
              {!readOnly && isDirectlyEditable && (
                <button type="button" onClick={async () => { if (!window.confirm(`Remove "${part.part_name || "Part"}" from this Product?`)) return; await removeManualProductPart(part.id, { builderProductId: part.builder_product_id, expectedEstimateUpdatedAt, expectedPartUpdatedAt: part.updated_date || "" }); await onChanged?.(); }} className="h-[28px] px-2.5 rounded border border-red-200 bg-white text-[11px] font-semibold text-red-600 hover:bg-red-50" title="Remove Part" aria-label={`Remove ${part.part_name || "Part"} from this Product`}><Trash2 className="w-3 h-3" aria-hidden="true" /></button>
              )}
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-3">
          <section className="rounded border border-gray-200 bg-white p-3">
            <div className="text-[9px] font-bold tracking-widest text-gray-400 mb-2">PART INFORMATION</div>
            <dl className="space-y-1.5 text-[11px]">
              <div className="flex justify-between gap-3"><dt className="text-gray-500">Type</dt><dd className="font-medium text-gray-800 text-right">{typeLabel(part)}</dd></div>
              {part.part_subtype && <div className="flex justify-between gap-3"><dt className="text-gray-500">Subtype</dt><dd className="font-medium text-gray-800 text-right">{String(part.part_subtype).replaceAll("_", " ")}</dd></div>}
              <div className="flex justify-between gap-3"><dt className="text-gray-500">Quantity</dt><dd className="font-medium text-gray-800 text-right">{num(part.quantity, 1).toLocaleString()} {part.unit || ""}</dd></div>
              <div className="flex justify-between gap-3"><dt className="text-gray-500">Builder source</dt><dd className="font-medium text-gray-800 text-right truncate max-w-[190px]">{part.source_module_key || "Manual"}</dd></div>
            </dl>
          </section>

          <section className="rounded border border-gray-200 bg-white p-3">
            <div className="text-[9px] font-bold tracking-widest text-gray-400 mb-2">MASTER INVENTORY LINK</div>
            <dl className="space-y-1.5 text-[11px]">
              <div className="flex justify-between gap-3"><dt className="text-gray-500">Status</dt><dd className="font-medium text-right">{part.inventory_link_state === "manual" ? "Manual / Builder cost" : String(part.inventory_link_state || "manual").replaceAll("_", " ")}</dd></div>
              {part.inventory_item_name && <div className="flex justify-between gap-3"><dt className="text-gray-500">Inventory Part</dt><dd className="font-medium text-gray-800 text-right truncate max-w-[190px]">{part.inventory_item_name}</dd></div>}
              {part.inventory_entity && <div className="flex justify-between gap-3"><dt className="text-gray-500">Inventory Type</dt><dd className="font-medium text-gray-800 text-right truncate max-w-[190px]">{part.inventory_entity}</dd></div>}
              {part.reattach_candidate_name && <div className="flex justify-between gap-3"><dt className="text-gray-500">Suggested match</dt><dd className="font-medium text-lime-700 text-right truncate max-w-[190px]">{part.reattach_candidate_name}</dd></div>}
            </dl>
          </section>

          <section className="rounded border border-gray-200 bg-white p-3">
            <div className="text-[9px] font-bold tracking-widest text-gray-400 mb-2">PRICING INFORMATION</div>
            <dl className="space-y-1.5 text-[11px]">
              <div className="flex justify-between gap-3"><dt className="text-gray-500">Frozen unit cost</dt><dd className="font-semibold text-gray-800">{money(num(part.frozen_unit_cost))}</dd></div>
              <div className="flex justify-between gap-3"><dt className="text-gray-500">Frozen extended</dt><dd className="font-semibold text-gray-800">{money(frozen)}</dd></div>
              <div className="flex justify-between gap-3"><dt className="text-gray-500">Current unit cost</dt><dd className={differs ? "font-semibold text-amber-700" : "font-semibold text-gray-800"}>{money(num(part.current_unit_cost, num(part.frozen_unit_cost)))}</dd></div>
              <div className="flex justify-between gap-3"><dt className="text-gray-500">Current extended</dt><dd className={differs ? "font-semibold text-amber-700" : "font-semibold text-gray-800"}>{money(current)}</dd></div>
            </dl>
          </section>

          <section className="rounded border border-gray-200 bg-white p-3">
            <div className="text-[9px] font-bold tracking-widest text-gray-400 mb-2">TYPE-SPECIFIC DETAILS</div>
            {inventoryDetails.length ? (
              <dl className="space-y-1.5 text-[11px] max-h-[170px] overflow-y-auto pr-1">
                {inventoryDetails.map((detail) => (
                  <div key={detail.field} className="flex justify-between gap-3 border-b border-gray-50 pb-1 last:border-b-0">
                    <dt className="text-gray-500 flex items-center gap-1">{detail.label}{detail.overridden && <span className="text-[8px] px-1 rounded bg-amber-100 text-amber-700 border border-amber-200">OVERRIDE</span>}</dt>
                    <dd className="font-medium text-gray-800 text-right max-w-[190px] break-words">
                      {Array.isArray(detail.value) ? detail.value.join(", ") : String(detail.value).replaceAll("_", " ")}
                    </dd>
                  </div>
                ))}
              </dl>
            ) : (
              <div className="text-[10px] text-gray-400">No additional type-specific inventory fields for this Part.</div>
            )}
          </section>
          </div>
        </div>
      )}

      <BuilderPartEditWarningModal
        open={warningOpen}
        part={part}
        onCancel={() => setWarningOpen(false)}
        onEditBuilder={() => {
          setWarningOpen(false);
          onEditBuilder?.();
        }}
        onDetach={async () => {
          await detachBuilderPartOverride(part.id, undefined, { expectedEstimateUpdatedAt, expectedPartUpdatedAt: part.updated_date || "" });
          setWarningOpen(false);
          setOverrideOpen(true);
          await onChanged?.();
        }}
      />
      <DetachedPartOverrideModal
        open={overrideOpen}
        part={part}
        mode={isDirectlyEditable ? "manual" : "detached"}
        onClose={() => setOverrideOpen(false)}
        onSave={async (changes) => {
          if (isDirectlyEditable) await updateManualProductPart(part.id, changes, { expectedEstimateUpdatedAt, expectedPartUpdatedAt: part.updated_date || "" });
          else await updateDetachedPartOverride(part.id, changes, { expectedEstimateUpdatedAt, expectedPartUpdatedAt: part.updated_date || "" });
          setOverrideOpen(false);
          await onChanged?.();
        }}
      />
      <SavePartTemplateModal
        open={saveLibraryOpen}
        itemType="part"
        part={part}
        estimateId={estimateId}
        builderProductId={part.builder_product_id}
        onClose={() => setSaveLibraryOpen(false)}
      />
      {isDirectlyEditable && (
        <MasterPartPickerModal
          open={switchOpen}
          mode="switch"
          suggestQuery={part.part_name || part.inventory_item_name || ""}
          initialQuantity={part.quantity || 1}
          onClose={() => setSwitchOpen(false)}
          onAdd={async (item) => {
            await switchManualProductPart(part.id, item, { expectedEstimateUpdatedAt, expectedPartUpdatedAt: part.updated_date || "" });
            setSwitchOpen(false);
            await onChanged?.();
          }}
        />
      )}
    </div>
  );
}

function PartGroup({ group, parts, globalOffset, selectionMode, selectedIds, onSelect, onChanged, builderProductId, onEditBuilder, estimateId, expectedEstimateUpdatedAt = "", availableProducts = [], readOnly = false }) {
  const [open, setOpen] = useState(!group.is_collapsed);
  const [visibleParts, setVisibleParts] = useState(PART_ROW_PAGE);
  const [renaming, setRenaming] = useState(false);
  const [name, setName] = useState(group.group_name || "Part Group");
  const [copying, setCopying] = useState(false);
  const [copied, setCopied] = useState(false);
  const [cloning, setCloning] = useState(false);
  const [moveOpen, setMoveOpen] = useState(false);
  const [saveLibraryOpen, setSaveLibraryOpen] = useState(false);
  const structuralActionRef = useRef(false);
  const groupVersionRef = useRef(group.updated_date || "");
  useEffect(() => {
    groupVersionRef.current = group.updated_date || groupVersionRef.current;
  }, [group.updated_date]);
  const frozen = parts.reduce((sum, part) => sum + num(part.frozen_extended_cost), 0);
  const canMove = parts.length > 0 && parts.every((part) => ["manual", "manual_addon"].includes(part.builder_sync_state));
  const moveTargets = (availableProducts || []).filter((line) => line.builder_product_id && line.builder_product_id !== builderProductId);

  const toggleOpen = async () => {
    const next = !open;
    setOpen(next);
    if (!readOnly) {
      const current = await base44.entities.BuilderPartGroup.get(group.id).catch(() => null);
      if (!current?.id || current.builder_product_id !== builderProductId) return;
      const collapsePatch = { is_collapsed: !next };
      const updated = await replaceBuilderEntityFieldsIfUnchanged({
        entity: base44.entities.BuilderPartGroup,
        id: group.id,
        expectedUpdatedAt: current.updated_date || "",
        expectedFields: expectedBuilderEntityFields(current, collapsePatch),
        nextFields: collapsePatch,
        guardFields: { builder_product_id: builderProductId },
        label: "Part Group collapsed state",
      }).catch(() => null);
      if (updated?.updated_date) groupVersionRef.current = updated.updated_date;
      else if (current?.updated_date) groupVersionRef.current = current.updated_date;
    }
  };

  const saveName = async () => {
    if (structuralActionRef.current) return;
    structuralActionRef.current = true;
    const nextName = name.trim() || "Part Group";
    setName(nextName);
    setRenaming(false);
    try {
      await renamePartGroup({
        builderProductId,
        groupId: group.id,
        groupName: nextName,
        expectedEstimateUpdatedAt,
        expectedGroupUpdatedAt: groupVersionRef.current,
      });
      await onChanged?.();
    } catch (error) {
      window.alert(error?.message || "Part Group could not be renamed.");
    } finally {
      structuralActionRef.current = false;
    }
  };

  const dissolve = async () => {
    if (structuralActionRef.current) return;
    if (!window.confirm(`Dissolve "${group.group_name || "Part Group"}"? The Parts will stay in this Product and keep all frozen pricing.`)) return;
    structuralActionRef.current = true;
    try {
      await dissolvePartGroup({
        builderProductId,
        groupId: group.id,
        expectedEstimateUpdatedAt,
        expectedGroupUpdatedAt: groupVersionRef.current,
        expectedPartVersions: Object.fromEntries(parts.map((part) => [part.id, part.updated_date || ""])),
      });
      await onChanged?.();
    } catch (error) {
      await Promise.resolve(onChanged?.()).catch(() => null);
      window.alert(`${error?.message || "Part Group could not be dissolved."}\n\nThe Product was refreshed. If the dissolve had already started, use Resume Group Dissolve to safely continue it.`);
    } finally {
      structuralActionRef.current = false;
    }
  };

  return (
    <div className="border border-gray-300 rounded-sm overflow-hidden bg-gray-50">
      <div className="w-full px-3 py-2 flex items-center gap-2 bg-gray-100 hover:bg-gray-200 text-left">
        <button type="button" onClick={toggleOpen} aria-expanded={open} className="flex items-center gap-2 min-w-0 flex-1 text-left">
        {open ? <ChevronDown className="w-3.5 h-3.5 text-gray-600" aria-hidden="true" /> : <ChevronRight className="w-3.5 h-3.5 text-gray-600" aria-hidden="true" />}
        <Layers3 className="w-4 h-4 text-gray-600" aria-hidden="true" />
          <span className="text-[9px] font-extrabold tracking-widest text-gray-500">PART GROUP</span>
          {renaming ? (
            <input
              autoFocus
              value={name}
              onChange={(event) => setName(event.target.value)}
              onClick={(event) => event.stopPropagation()}
              aria-label="Part Group name"
              onKeyDown={(event) => {
                if (event.key === "Enter") {
                  event.preventDefault();
                  saveName();
                }
                if (event.key === "Escape") {
                  setName(group.group_name || "Part Group");
                  setRenaming(false);
                }
              }}
              onBlur={saveName}
              className="h-[25px] px-2 border border-gray-300 rounded bg-white text-[12px] font-bold text-gray-900 flex-1 min-w-[120px]"
            />
          ) : (
            <span className="text-[12px] font-bold text-gray-900 truncate flex-1">{group.group_name || "Part Group"}</span>
          )}
          <span className="text-[10px] text-gray-500">{parts.length} parts</span>
          <span className="text-[11px] font-bold text-gray-800 w-[92px] text-right">{money(frozen)}</span>
        </button>
        {!selectionMode && (
          <div className="flex items-center gap-1 ml-1">
            {estimateId && (
              <button
                type="button"
                disabled={copying}
                onClick={async () => {
                  setCopying(true);
                  try {
                    await copyPartGroupToClipboard({ estimateId, builderProductId, group, parts });
                    setCopied(true);
                    setTimeout(() => setCopied(false), 1500);
                  } catch (error) {
                    window.alert(error?.message || "Part Group could not be copied to the estimator clipboard.");
                  } finally {
                    setCopying(false);
                  }
                }}
                className="h-[26px] px-2 rounded border border-gray-300 bg-white flex items-center gap-1 text-[10px] font-semibold text-gray-600 hover:bg-gray-50 disabled:opacity-50"
                title="Copy Part Group to 30-day Clipboard"
                aria-label={`Copy ${group.group_name || "Part Group"} to 30-day clipboard`}
              ><ClipboardCopy className="w-3 h-3" aria-hidden="true" /> {copied ? "Copied" : "Copy"}</button>
            )}
            <button
              type="button"
              onClick={() => setSaveLibraryOpen(true)}
              className="h-[26px] px-2 rounded border border-violet-200 bg-white flex items-center gap-1 text-[10px] font-semibold text-violet-700 hover:bg-violet-50"
              title="Save Part Group permanently to Part Library"
              aria-label={`Save ${group.group_name || "Part Group"} permanently to Part Library`}
            ><BookmarkPlus className="w-3 h-3" aria-hidden="true" /> Save</button>
            {!readOnly && <>
              <button
                type="button"
                disabled={cloning}
                onClick={async () => {
                  if (!window.confirm(`Clone "${group.group_name || "Part Group"}" and all ${parts.length} Part${parts.length === 1 ? "" : "s"}?`)) return;
                  if (structuralActionRef.current) return;
                  structuralActionRef.current = true;
                  setCloning(true);
                  try {
                    await clonePartGroupInProduct({
                      builderProductId,
                      groupId: group.id,
                      expectedEstimateUpdatedAt,
                      expectedGroupUpdatedAt: groupVersionRef.current,
                      expectedPartVersions: Object.fromEntries(parts.map((part) => [part.id, part.updated_date || ""])),
                    });
                    await onChanged?.();
                  } catch (error) {
                    await Promise.resolve(onChanged?.()).catch(() => null);
                    window.alert(`${error?.message || "Part Group could not be cloned."}\n\nThe Product was refreshed. If the clone had already started, use Resume Group Clone to safely continue it.`);
                  } finally {
                    structuralActionRef.current = false;
                    setCloning(false);
                  }
                }}
                className="h-[26px] px-2 rounded border border-gray-300 bg-white flex items-center gap-1 text-[10px] font-semibold text-gray-600 hover:bg-gray-50 disabled:opacity-50"
                title="Clone Part Group in this Product"
                aria-label={`Clone ${group.group_name || "Part Group"} in this Product`}
              ><CopyPlus className="w-3 h-3" aria-hidden="true" /> {cloning ? "Cloning…" : "Clone"}</button>
              <button
                type="button"
                disabled={!canMove || moveTargets.length === 0}
                onClick={() => setMoveOpen(true)}
                className="h-[26px] px-2 rounded border border-gray-300 bg-white flex items-center gap-1 text-[10px] font-semibold text-gray-600 hover:bg-gray-50 disabled:opacity-40"
                title={canMove ? "Move Part Group to another Product" : "Builder-owned Parts cannot move directly. Use Clone or Copy instead."}
                aria-label={canMove ? `Move ${group.group_name || "Part Group"} to another Product` : "Builder-owned Parts cannot move directly. Use Clone or Copy instead."}
              ><ArrowRightLeft className="w-3 h-3" aria-hidden="true" /> Move</button>
              <button
                type="button"
                onClick={() => setRenaming(true)}
                className="w-[26px] h-[26px] rounded border border-gray-300 bg-white flex items-center justify-center text-gray-600 hover:bg-gray-50"
                title="Rename Part Group"
                aria-label={`Rename ${group.group_name || "Part Group"}`}
              >
                <Pencil className="w-3 h-3" aria-hidden="true" />
              </button>
              <button
                type="button"
                onClick={dissolve}
                className="w-[26px] h-[26px] rounded border border-gray-300 bg-white flex items-center justify-center text-gray-500 hover:text-red-600 hover:bg-red-50"
                title="Dissolve Part Group"
                aria-label={`Dissolve ${group.group_name || "Part Group"}`}
              >
                <Unlink className="w-3 h-3" aria-hidden="true" />
              </button>
            </>}
          </div>
        )}
      </div>
      {open && (
        <div className="p-2 space-y-2 border-t border-gray-200">
          {parts.slice(0, visibleParts).map((part, index) => (
            <PartRow
              key={part.id}
              part={part}
              index={globalOffset + index}
              selectionMode={selectionMode}
              selected={selectedIds.has(part.id)}
              onSelect={onSelect}
              onChanged={onChanged}
              onEditBuilder={onEditBuilder}
              estimateId={estimateId}
              expectedEstimateUpdatedAt={expectedEstimateUpdatedAt}
              readOnly={readOnly}
            />
          ))}
          {parts.length > visibleParts && (
            <button
              type="button"
              onClick={() => setVisibleParts((value) => value + PART_ROW_PAGE)}
              className="w-full h-[28px] rounded border border-gray-300 bg-white text-[10px] font-bold text-gray-600 hover:bg-gray-50"
            >
              Show {Math.min(PART_ROW_PAGE, parts.length - visibleParts)} more parts ({parts.length - visibleParts} remaining)
            </button>
          )}
        </div>
      )}
      <MovePartGroupModal
        open={moveOpen}
        group={group}
        sourceBuilderProductId={builderProductId}
        products={moveTargets}
        onClose={() => setMoveOpen(false)}
        onMove={async (targetBuilderProductId) => {
          if (structuralActionRef.current) return;
          structuralActionRef.current = true;
          try {
            await moveIndependentPartGroup({
              sourceBuilderProductId: builderProductId,
              targetBuilderProductId,
              groupId: group.id,
              expectedEstimateUpdatedAt,
              expectedGroupUpdatedAt: groupVersionRef.current,
              expectedPartVersions: Object.fromEntries(parts.map((part) => [part.id, part.updated_date || ""])),
            });
            setMoveOpen(false);
            await onChanged?.();
          } catch (error) {
            await Promise.resolve(onChanged?.()).catch(() => null);
            throw new Error(`${error?.message || "Part Group could not be moved."}\n\nThe Products were refreshed. If the move had already started, use Resume Group Move to safely continue it.`);
          } finally {
            structuralActionRef.current = false;
          }
        }}
      />
      <SavePartTemplateModal
        open={saveLibraryOpen}
        itemType="part_group"
        group={group}
        parts={parts}
        estimateId={estimateId}
        builderProductId={builderProductId}
        onClose={() => setSaveLibraryOpen(false)}
      />
    </div>
  );
}

export default function BuilderPartsPanel({ builderProductId, refreshKey, onLoaded, onEditBuilder, onProductRefresh, allowAddParts = false, estimateId, expectedEstimateUpdatedAt = "", availableProducts = [], readOnly = false }) {
  const [loading, setLoading] = useState(!!builderProductId);
  const [parts, setParts] = useState([]);
  const [groups, setGroups] = useState([]);
  const [dragGroupIdx, setDragGroupIdx] = useState(null);
  const [dragOverIdx, setDragOverIdx] = useState(null);
  const [selectionMode, setSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState(new Set());
  const [groupModalOpen, setGroupModalOpen] = useState(false);
  const [partPickerOpen, setPartPickerOpen] = useState(false);
  const [partLibraryOpen, setPartLibraryOpen] = useState(false);
  const [refreshNonce, setRefreshNonce] = useState(0);
  const [partSearch, setPartSearch] = useState("");
  const [ungroupedVisible, setUngroupedVisible] = useState(PART_ROW_PAGE);
  const [bulkRemoving, setBulkRemoving] = useState(false);
  const [bulkDetaching, setBulkDetaching] = useState(false);
  const groupCreateRef = useRef(false);

  useEffect(() => {
    let active = true;
    const load = async () => {
      if (!builderProductId) {
        setParts([]);
        setGroups([]);
        setLoading(false);
        onLoaded?.(0);
        return;
      }
      setLoading(true);
      try {
        const [partRows, groupRows] = await Promise.all([
          loadAllEntityRows({ entity: base44.entities.BuilderPart, query: { builder_product_id: builderProductId }, sort: "sort_order", label: "Builder Parts panel Parts" }),
          loadAllEntityRows({ entity: base44.entities.BuilderPartGroup, query: { builder_product_id: builderProductId }, sort: "sort_order", label: "Builder Parts panel Groups" }),
        ]);
        if (!active) return;
        const activeParts = (partRows || [])
          .filter((part) => part.is_active !== false)
          .sort((a, b) => num(a.sort_order) - num(b.sort_order));
        const activeGroups = (groupRows || [])
          .filter((group) => group.is_active !== false)
          .sort((a, b) => num(a.sort_order) - num(b.sort_order));
        setParts(activeParts);
        setGroups(activeGroups);
        onLoaded?.(activeParts.length);
      } finally {
        if (active) setLoading(false);
      }
    };
    load();
    return () => {
      active = false;
    };
  }, [builderProductId, refreshKey, refreshNonce]);

  const togglePartSelection = (partId, checked) => {
    setSelectedIds((current) => {
      const next = new Set(current);
      if (checked) next.add(partId);
      else next.delete(partId);
      return next;
    });
  };

  const cancelSelection = () => {
    setSelectionMode(false);
    setSelectedIds(new Set());
    setGroupModalOpen(false);
  };

  const removableSelected = parts.filter((part) => selectedIds.has(part.id) && ["manual", "manual_addon"].includes(part.builder_sync_state));

  const bulkRemoveSelected = async () => {
    if (!builderProductId || bulkRemoving || !removableSelected.length) return;
    const skipped = selectedIds.size - removableSelected.length;
    const message = skipped > 0
      ? `Remove ${removableSelected.length} independent Part${removableSelected.length === 1 ? "" : "s"}? ${skipped} Builder-linked Part${skipped === 1 ? "" : "s"} will be kept (remove those through the Builder).`
      : `Remove ${removableSelected.length} independent Part${removableSelected.length === 1 ? "" : "s"} from this Product?`;
    if (!window.confirm(message)) return;
    setBulkRemoving(true);
    const failures = [];
    try {
      for (const part of removableSelected) {
        try {
          await removeManualProductPart(part.id, { builderProductId, expectedEstimateUpdatedAt, expectedPartUpdatedAt: part.updated_date || "" });
        } catch (error) {
          failures.push(`${part.part_name || "Part"}: ${error?.message || "remove failed"}`);
        }
      }
      setSelectionMode(false);
      setSelectedIds(new Set());
      setRefreshNonce((value) => value + 1);
      await onProductRefresh?.();
      if (failures.length) {
        window.alert(`${failures.length} Part${failures.length === 1 ? "" : "s"} could not be removed:\n${failures.join("\n")}\n\nThe Product was refreshed. If a removal had already started, use Resume Part Remove to safely continue it.`);
      }
    } finally {
      setBulkRemoving(false);
    }
  };

  const detachableSelected = parts.filter((part) => selectedIds.has(part.id) && part.builder_sync_state === "linked");

  const bulkDetachSelected = async () => {
    if (!builderProductId || bulkDetaching || !detachableSelected.length) return;
    if (!window.confirm(`Detach ${detachableSelected.length} Builder-linked Part${detachableSelected.length === 1 ? "" : "s"} for independent override? Frozen pricing is retained; each Part stops syncing with the Builder.`)) return;
    setBulkDetaching(true);
    const failures = [];
    try {
      for (const part of detachableSelected) {
        try {
          await detachBuilderPartOverride(part.id, undefined, { expectedEstimateUpdatedAt, expectedPartUpdatedAt: part.updated_date || "" });
        } catch (error) {
          failures.push(`${part.part_name || "Part"}: ${error?.message || "detach failed"}`);
        }
      }
      setSelectionMode(false);
      setSelectedIds(new Set());
      setRefreshNonce((value) => value + 1);
      await onProductRefresh?.();
      if (failures.length) {
        window.alert(`${failures.length} Part${failures.length === 1 ? "" : "s"} could not be detached:\n${failures.join("\n")}\n\nThe Product was refreshed. If a detach had already started, use Resume Part Detach to safely continue it.`);
      }
    } finally {
      setBulkDetaching(false);
    }
  };

  const createGroup = async (groupName) => {
    const selectedParts = parts.filter((part) => selectedIds.has(part.id));
    if (!builderProductId || selectedParts.length < 2 || groupCreateRef.current) return;
    groupCreateRef.current = true;
    try {
      await createPartGroupInProduct({
        builderProductId,
        partIds: selectedParts.map((part) => part.id),
        groupName,
        expectedEstimateUpdatedAt,
        expectedPartVersions: Object.fromEntries(selectedParts.map((part) => [part.id, part.updated_date || ""])),
      });
      setGroupModalOpen(false);
      setSelectionMode(false);
      setSelectedIds(new Set());
      setRefreshNonce((value) => value + 1);
      await onProductRefresh?.();
    } catch (error) {
      setRefreshNonce((value) => value + 1);
      await Promise.resolve(onProductRefresh?.()).catch(() => null);
      window.alert(`${error?.message || "Part Group could not be created."}\n\nThe Product was refreshed. If creation had already started, use Resume Group Create to safely continue it.`);
    } finally {
      groupCreateRef.current = false;
    }
  };

  const partQuery = partSearch.trim().toLowerCase();
  const visibleParts = useMemo(() => {
    if (!partQuery) return parts;
    return parts.filter((part) =>
      [part.part_name, part.client_label, part.inventory_item_name, part.part_type, part.part_subtype]
        .filter(Boolean)
        .some((value) => String(value).toLowerCase().includes(partQuery))
    );
  }, [parts, partQuery]);

  const grouped = useMemo(() => {
    const byGroup = new Map();
    groups.forEach((group) => byGroup.set(group.id, []));
    const ungrouped = [];
    visibleParts.forEach((part) => {
      if (part.part_group_id && byGroup.has(part.part_group_id)) byGroup.get(part.part_group_id).push(part);
      else ungrouped.push(part);
    });
    return { byGroup, ungrouped };
  }, [visibleParts, groups]);

  if (!builderProductId) {
    return <div className="px-4 py-4 text-[11px] text-gray-400">This legacy Product does not have Builder Parts yet.</div>;
  }
  if (loading) {
    return <div role="status" className="px-4 py-4 text-[11px] text-gray-400">Loading Parts…</div>;
  }
  if (!parts.length) {
    return (
      <div className="px-4 py-5 text-center border-t border-gray-200 bg-gray-50">
        <div className="text-[11px] font-semibold text-gray-600">This Product does not have any Parts yet.</div>
        <div className="text-[10px] text-gray-400 mt-1">Add a Part from Master Inventory now. Builder-generated BOM Parts will also appear here after the Builder is saved; manually added Parts remain independent add-ons.</div>
        {allowAddParts && !readOnly && (
          <div className="mt-3 flex items-center justify-center gap-2">
            <button type="button" onClick={() => setPartPickerOpen(true)} className="h-[30px] px-3 rounded border border-lime-400 bg-lime-200 text-[11px] font-bold text-gray-900 hover:bg-lime-300 inline-flex items-center gap-1.5"><Plus className="w-3.5 h-3.5" aria-hidden="true" /> Add Part</button>
            <button type="button" onClick={() => setPartLibraryOpen(true)} className="h-[30px] px-3 rounded border border-violet-200 bg-white text-[11px] font-bold text-violet-700 hover:bg-violet-50 inline-flex items-center gap-1.5"><BookmarkPlus className="w-3.5 h-3.5" aria-hidden="true" /> Add Saved Part</button>
            <CopyBomButton estimateId={estimateId} targetBuilderProductId={builderProductId} expectedEstimateUpdatedAt={expectedEstimateUpdatedAt} />
          </div>
        )}
        <MasterPartPickerModal
          open={partPickerOpen}
          onClose={() => setPartPickerOpen(false)}
          onAdd={async (item, quantity) => {
            await addCatalogPartToProduct({ builderProductId, catalogItem: item, quantity, expectedEstimateUpdatedAt });
            setRefreshNonce((value) => value + 1);
            await onProductRefresh?.();
          }}
        />
        <PartLibraryPickerModal
          open={partLibraryOpen}
          estimateId={estimateId}
          builderProductId={builderProductId}
          expectedEstimateUpdatedAt={expectedEstimateUpdatedAt}
          onClose={() => setPartLibraryOpen(false)}
          onAdded={async () => {
            setRefreshNonce((value) => value + 1);
            await onProductRefresh?.();
          }}
        />
      </div>
    );
  }

  let offset = 0;
  const partsFrozenTotal = parts.reduce((sum, part) => sum + num(part.frozen_extended_cost), 0);
  const persistGroupOrder = async (nextGroups) => {
    for (let i = 0; i < nextGroups.length; i++) {
      const g = nextGroups[i];
      if (Number(g.sort_order) !== i) {
        await staffEntities.BuilderPartGroup.updateMany({ id: g.id }, { sort_order: i }).catch(() => null);
      }
    }
  };


  return (
    <div className="border-t border-gray-300 bg-[#f6f6f6] px-3 py-3 space-y-2">
      <div className="flex items-center justify-between gap-2 pb-1">
        <div className="flex items-center gap-2 min-w-0">
          <div className="text-[10px] font-bold tracking-widest text-gray-500 whitespace-nowrap">PRODUCT PARTS · {partQuery ? `${visibleParts.length}/${parts.length}` : parts.length}</div>
          {parts.length > 10 && (
            <div className="relative">
              <Search className="w-3 h-3 text-gray-400 absolute left-1.5 top-1/2 -translate-y-1/2 pointer-events-none" aria-hidden="true" />
              <input
                value={partSearch}
                onChange={(event) => setPartSearch(event.target.value)}
                placeholder="Search parts…"
                aria-label="Search parts in this product"
                className="h-[26px] w-[150px] pl-6 pr-1.5 border border-gray-300 rounded bg-white text-[11px] focus:outline-none focus:border-lime-400"
              />
            </div>
          )}
        </div>
        {selectionMode ? (
          <div className="flex items-center gap-2">
            <span className="text-[10px] text-gray-500">{selectedIds.size} selected</span>
            <button
              type="button"
              onClick={cancelSelection}
              className="h-[28px] px-3 rounded border border-gray-300 bg-white text-[11px] font-semibold text-gray-600 hover:bg-gray-50"
            >
              Cancel
            </button>
            <button
              type="button"
              disabled={selectedIds.size < 2}
              onClick={() => setGroupModalOpen(true)}
              className="h-[28px] px-3 rounded border border-lime-400 bg-lime-200 text-[11px] font-bold text-gray-900 hover:bg-lime-300 disabled:opacity-40"
            >
              Group Selected Parts
            </button>
            <button
              type="button"
              disabled={bulkDetaching || detachableSelected.length === 0}
              onClick={bulkDetachSelected}
              title={detachableSelected.length === 0 ? "Only Builder-linked Parts can be detached" : "Detach the selected Builder-linked Parts for independent override"}
              className="h-[28px] px-3 rounded border border-amber-300 bg-white text-[11px] font-bold text-amber-700 hover:bg-amber-50 disabled:opacity-40 inline-flex items-center gap-1"
            >
              <Unlink className="w-3.5 h-3.5" aria-hidden="true" /> {bulkDetaching ? "Detaching…" : `Detach Selected (${detachableSelected.length})`}
            </button>
            <button
              type="button"
              disabled={bulkRemoving || removableSelected.length === 0}
              onClick={bulkRemoveSelected}
              title={removableSelected.length === 0 ? "Only independent (non-Builder) Parts can be removed here" : "Remove the selected independent Parts"}
              className="h-[28px] px-3 rounded border border-red-300 bg-white text-[11px] font-bold text-red-600 hover:bg-red-50 disabled:opacity-40 inline-flex items-center gap-1"
            >
              <Trash2 className="w-3.5 h-3.5" aria-hidden="true" /> {bulkRemoving ? "Removing…" : `Delete Selected (${removableSelected.length})`}
            </button>
          </div>
        ) : (
          <div className="flex items-center gap-2">
            {allowAddParts && !readOnly && (
              <>
                <button type="button" onClick={() => setPartPickerOpen(true)} className="h-[28px] px-3 rounded border border-lime-400 bg-lime-200 text-[11px] font-bold text-gray-900 hover:bg-lime-300 inline-flex items-center gap-1.5"><Plus className="w-3.5 h-3.5" aria-hidden="true" /> Add Part</button>
                <button type="button" onClick={() => setPartLibraryOpen(true)} className="h-[28px] px-3 rounded border border-violet-200 bg-white text-[11px] font-bold text-violet-700 hover:bg-violet-50 inline-flex items-center gap-1.5"><BookmarkPlus className="w-3.5 h-3.5" aria-hidden="true" /> Add Saved Part</button>
                <CopyBomButton estimateId={estimateId} targetBuilderProductId={builderProductId} expectedEstimateUpdatedAt={expectedEstimateUpdatedAt} />
              </>
            )}
            {!readOnly && <button
              type="button"
              onClick={() => setSelectionMode(true)}
              className="h-[28px] px-3 rounded border border-gray-300 bg-white text-[11px] font-semibold text-gray-700 hover:bg-gray-100 inline-flex items-center gap-1.5"
            >
              <Layers3 className="w-3.5 h-3.5" aria-hidden="true" /> Group Parts
            </button>}
          </div>
        )}
      </div>

      {groups.map((group) => {
        const groupParts = grouped.byGroup.get(group.id) || [];
        if (!groupParts.length) return null;
        const node = (
          <PartGroup
            key={group.id}
            group={group}
            parts={groupParts}
            globalOffset={offset}
            selectionMode={selectionMode}
            selectedIds={selectedIds}
            onSelect={togglePartSelection}
            onChanged={async () => {
              setRefreshNonce((value) => value + 1);
              await onProductRefresh?.();
            }}
            builderProductId={builderProductId}
            onEditBuilder={onEditBuilder}
            estimateId={estimateId}
            expectedEstimateUpdatedAt={expectedEstimateUpdatedAt}
            availableProducts={availableProducts}
            readOnly={readOnly}
          />
        );
        offset += groupParts.length;
        return readOnly ? node : (
          <div
            key={group.id}
            draggable
            onDragStart={() => setDragGroupIdx(groups.indexOf(group))}
            onDragOver={(e) => { e.preventDefault(); setDragOverIdx(groups.indexOf(group)); }}
            onDragLeave={() => setDragOverIdx(null)}
            onDrop={async (e) => {
              e.preventDefault();
              if (dragGroupIdx === null) return;
              const target = groups.indexOf(group);
              const next = [...groups];
              const [moved] = next.splice(dragGroupIdx, 1);
              next.splice(target, 0, moved);
              setGroups(next);
              setDragGroupIdx(null);
              setDragOverIdx(null);
              await persistGroupOrder(next);
              setRefreshNonce((v) => v + 1);
            }}
            onDragEnd={() => { setDragGroupIdx(null); setDragOverIdx(null); }}
            className={`${dragOverIdx === groups.indexOf(group) ? "ring-2 ring-emerald-400 rounded" : ""}`}
          >
            {node}
          </div>
        );
      })}
      {grouped.ungrouped.slice(0, partQuery ? grouped.ungrouped.length : ungroupedVisible).map((part, index) => (
        <PartRow
          key={part.id}
          part={part}
          index={offset + index}
          selectionMode={selectionMode}
          selected={selectedIds.has(part.id)}
          onSelect={togglePartSelection}
          onChanged={async () => {
            setRefreshNonce((value) => value + 1);
            await onProductRefresh?.();
          }}
          onEditBuilder={onEditBuilder}
          estimateId={estimateId}
          expectedEstimateUpdatedAt={expectedEstimateUpdatedAt}
          readOnly={readOnly}
        />
      ))}
      {!partQuery && grouped.ungrouped.length > ungroupedVisible && (
        <button
          type="button"
          onClick={() => setUngroupedVisible((value) => value + PART_ROW_PAGE)}
          className="w-full h-[28px] rounded border border-gray-300 bg-white text-[10px] font-bold text-gray-600 hover:bg-gray-50"
        >
          Show {Math.min(PART_ROW_PAGE, grouped.ungrouped.length - ungroupedVisible)} more parts ({grouped.ungrouped.length - ungroupedVisible} remaining)
        </button>
      )}
      {partQuery && !visibleParts.length && (
        <div className="py-4 text-center text-[11px] text-gray-400">No Parts match "{partSearch}".</div>
      )}

      <div className="flex items-center justify-between gap-2 pt-2 border-t border-gray-200">
        <div className="text-[10px] font-bold tracking-widest text-gray-500">PARTS TOTAL</div>
        <div className="text-[11px] font-bold text-gray-800">{money(partsFrozenTotal)}</div>
      </div>

      <CreatePartGroupModal
        open={groupModalOpen}
        selectedCount={selectedIds.size}
        onClose={() => setGroupModalOpen(false)}
        onCreate={createGroup}
      />
      <MasterPartPickerModal
        open={partPickerOpen}
        onClose={() => setPartPickerOpen(false)}
        onAdd={async (item, quantity) => {
          await addCatalogPartToProduct({ builderProductId, catalogItem: item, quantity, expectedEstimateUpdatedAt });
          setRefreshNonce((value) => value + 1);
          await onProductRefresh?.();
        }}
      />
      <PartLibraryPickerModal
        open={partLibraryOpen}
        estimateId={estimateId}
        builderProductId={builderProductId}
        expectedEstimateUpdatedAt={expectedEstimateUpdatedAt}
        onClose={() => setPartLibraryOpen(false)}
        onAdded={async () => {
          setRefreshNonce((value) => value + 1);
          await onProductRefresh?.();
        }}
      />
    </div>
  );
}

import { base44 } from "@/api/base44Client";
import { getModuleLabel } from "./moduleRegistry";
import { acceptedInternalEstimateCost, acceptedCustomerUnitPrice } from "./customerPricing";
import { hasVerifiedEstimateSalesActivity } from "./estimateSalesActivity.mjs";
import { ensureEstimateLifecycleRevision } from "./estimateRevisionService";
import { getPendingEstimatePriceAcceptance } from "./estimateMutationGuard";
import { localDateStamp } from "./quoteLifecycle";
import { loadAllEntityRows } from "./loadAllEntityRows";
import { convergeCreatedEstimateWorkOrder, loadAllCustomers, resolveCustomerForEstimate } from "./customerSync";
import { replaceWorkOrderFieldsIfUnchanged } from "@/components/workflow/workOrderPersistence";
import { createEstimateLinkedWorkOrderWithRecovery, expectedWorkOrderFields } from "./workOrderSyncPersistence";
import { expectedEstimateFields, replaceEstimateFieldsIfUnchanged } from "./estimatePersistence";
import { staffEntities } from "@/components/staff/staffEntities";
import {
  buildConvertedWorkOrderFields,
  buildEstimateWorkOrderProducts,
  estimateConvertedAmount,
  mergeWorkOrderProducts,
  selectExistingEstimateWorkOrder,
} from "./workOrderConversion";

const num = (value, fallback = 0) => (Number.isFinite(Number(value)) ? Number(value) : fallback);
const str = (value) => String(value ?? "").trim();

// Platform-user conversion (EstimateDetail) reads through base44.entities;
// staff-session flows (EstimatorQueues bulk) must go through the staffEntity
// gateways — caller picks, defaults keep the original component's clients.
const defaultEntities = () => ({
  Estimate: base44.entities.AllInOneEstimate,
  WorkOrder: base44.entities.WorkOrder,
});

// Per-module WO task templates: each estimate section contributes its
// module's prep tasks ahead of the section line itself. Mirrors the seed
// list customerSync.syncEstimateToPipeline uses for brand-new jobs — kept
// here so conversion paths share the same checklist shape.
export const ESTIMATE_SECTION_TASK_TEMPLATES = {
  channel_letters: ["Verify letter pattern & depth before production", "Confirm raceway/wireway routing with site"],
  foundation: ["Confirm footing depth/diameter with site conditions", "Order concrete & schedule pour window"],
  vinyl: ["Confirm surface prep & temperature window", "Order vinyl media and laminate"],
  cnc: ["Approve cut file/toolpath before material pull", "Verify sheet stock on hand"],
  laser: ["Approve cut file before material pull", "Verify sheet stock thickness on hand"],
  metal: ["Confirm weld/finish spec with drawings", "Order metal stock & consumables"],
  brick_stone: ["Confirm substrate/masonry anchoring spec", "Stage stone/material before install"],
  maintenance: ["Schedule service window with customer", "Stage replacement parts/lamps"],
  painting: ["Confirm color/sheen approval with customer", "Mask & prep surfaces before spray"],
};

export function buildEstimateWorkOrderSeedTasks(estimate, { idPrefix = "" } = {}) {
  return (Array.isArray(estimate?.line_items) ? estimate.line_items : [])
    .flatMap((line) => {
      const moduleKey = str(line?.module_key);
      const template = (ESTIMATE_SECTION_TASK_TEMPLATES[moduleKey] || []).map((text, i) => ({
        id: `${idPrefix}tpl_${moduleKey}_${line?.line_id || i}_${i}`,
        text,
        completed: false,
      }));
      const sectionTask = {
        id: `${idPrefix}sec_${line?.line_id || Math.random().toString(36).slice(2, 10)}`,
        text: `Estimate section: ${line?.client_product_name || line?.builder_name || moduleKey || "Product"}`,
        completed: false,
      };
      return sectionTask.text !== "Estimate section: Product" ? [...template, sectionTask] : template;
    });
}

// Union task lists by task id, then by text — a live WO checklist is never
// overwritten; combined conversion appends only the new estimate's seeds.
export function mergeWorkOrderTasks(existing = [], incoming = []) {
  const merged = [...(Array.isArray(existing) ? existing : [])];
  const ids = new Set(merged.map((t) => str(t?.id)).filter(Boolean));
  const texts = new Set(merged.map((t) => str(t?.text)).filter(Boolean));
  for (const task of incoming || []) {
    const id = str(task?.id);
    const text = str(task?.text);
    if ((id && ids.has(id)) || (text && texts.has(text))) continue;
    if (id) ids.add(id);
    if (text) texts.add(text);
    merged.push(task);
  }
  return merged;
}

// WO.materials manifest — FLATTENED shape (not per-section nested): the WO
// detail/production views consume materials as a flat pick/cost list, and
// every row keeps its full provenance (source_estimate_id,
// source_estimate_number, estimate_line_id, builder_product_id, module_key,
// section_name) so section-level pricing origin survives the merge onto the
// WorkOrder. Costs come from the BuilderPart frozen snapshots — the prices
// the customer actually approved.
export async function buildEstimateMaterialsManifest(estimate, { parts = null } = {}) {
  const estimateId = str(estimate?.id);
  if (!estimateId) return [];
  const lines = Array.isArray(estimate?.line_items) ? estimate.line_items : [];
  const lineByProduct = new Map();
  for (const line of lines) {
    const bpid = str(line?.builder_product_id);
    if (bpid) lineByProduct.set(bpid, line);
  }
  let allParts = parts;
  if (!Array.isArray(allParts)) {
    allParts = [];
    const seen = new Set();
    // Primary path: parts stamped with estimate_id (partSync writes it).
    const byEstimate = await loadAllEntityRows({
      entity: staffEntities.BuilderPart,
      query: { estimate_id: estimateId },
      sort: "created_date",
      label: "Conversion materials manifest",
    }).catch(() => []);
    for (const p of byEstimate) {
      const id = str(p?.id);
      if (id && !seen.has(id)) { seen.add(id); allParts.push(p); }
    }
    // Fallback: older parts predate estimate_id — resolve through each
    // section's BuilderProduct link instead.
    for (const bpid of lineByProduct.keys()) {
      if (allParts.some((p) => str(p?.builder_product_id) === bpid)) continue;
      const rows = await staffEntities.BuilderPart.filter({ builder_product_id: bpid }, "created_date", 500).catch(() => []);
      for (const p of rows || []) {
        const id = str(p?.id);
        if (id && !seen.has(id)) { seen.add(id); allParts.push(p); }
      }
    }
  }
  return allParts
    .filter((p) => p && p.is_active !== false)
    .map((p) => {
      const line = lineByProduct.get(str(p?.builder_product_id)) || null;
      return {
        builder_part_id: str(p?.id),
        part_key: str(p?.part_key),
        part_name: str(p?.part_name) || str(p?.client_label) || str(p?.inventory_item_name) || "Part",
        part_type: str(p?.part_type),
        part_subtype: str(p?.part_subtype),
        quantity: num(p?.quantity, 1),
        unit: str(p?.unit),
        unit_cost: num(p?.frozen_unit_cost),
        extended_cost: num(p?.frozen_extended_cost),
        inventory_item_id: str(p?.inventory_item_id),
        inventory_item_name: str(p?.inventory_item_name),
        source: "estimate_conversion",
        source_estimate_id: estimateId,
        source_estimate_number: str(estimate?.estimate_number),
        estimate_line_id: str(line?.line_id),
        builder_product_id: str(p?.builder_product_id),
        module_key: str(line?.module_key) || str(p?.source_module_key),
        section_name: str(line?.client_product_name || line?.project_name),
      };
    })
    .sort((a, b) => a.part_name.localeCompare(b.part_name));
}

// Merge materials onto an existing WO manifest. Existing rows win by
// identity (builder_part_id + source_estimate_id) so a re-conversion or a
// combined merge never duplicates a material line already on the job.
export function mergeWorkOrderMaterials(existing = [], incoming = []) {
  const merged = [...(Array.isArray(existing) ? existing : [])];
  const keys = new Set(merged.map((m) => `${str(m?.builder_part_id)}|${str(m?.source_estimate_id)}`));
  for (const row of incoming || []) {
    const key = `${str(row?.builder_part_id)}|${str(row?.source_estimate_id)}`;
    if (keys.has(key)) continue;
    keys.add(key);
    merged.push(row);
  }
  return merged;
}

// Validate the caller's loaded estimate against live state and resolve the
// WorkOrder it would convert onto (existing or none) plus the verified
// shared Customer link. Pure reads — throws with the user-facing reason.
export async function prepareEstimateConversion({
  estimate,
  expectedUpdatedDate = undefined,
  entities = null,
  sharedWorkOrder = undefined,
} = {}) {
  const { Estimate, WorkOrder } = entities || defaultEntities();
  const estimateBefore = await Estimate.get(str(estimate?.id));
  const pendingPrice = getPendingEstimatePriceAcceptance(estimateBefore);
  if (pendingPrice) {
    const name = pendingPrice.line?.client_product_name || pendingPrice.line?.project_name || "Product";
    const resumeLabel = pendingPrice.pending?.kind === "builder_initial_freeze"
      ? "Resume Initial Price"
      : pendingPrice.pending?.kind === "builder_detach_override"
        ? "Resume Part Detach"
        : pendingPrice.pending?.kind === "builder_detached_override_update"
          ? "Resume Part Change"
          : pendingPrice.pending?.kind === "builder_reattach_parts"
            ? "Resume Reattach"
            : pendingPrice.pending?.kind === "builder_manual_part_add"
              ? "Resume Part Add"
              : pendingPrice.pending?.kind === "builder_manual_part_edit"
                ? "Resume Part Edit"
                : pendingPrice.pending?.kind === "builder_manual_part_switch"
                  ? "Resume Part Switch"
                  : pendingPrice.pending?.kind === "builder_manual_part_remove"
                    ? "Resume Part Remove"
                    : pendingPrice.pending?.kind === "builder_part_package_add"
                      ? "Resume Part Insert"
                      : pendingPrice.pending?.kind === "builder_manual_product_price"
                        ? "Resume Product Price"
                        : pendingPrice.pending?.kind === "builder_part_group_clone"
                          ? "Resume Group Clone"
                          : pendingPrice.pending?.kind === "builder_part_group_move"
                            ? "Resume Group Move"
                            : pendingPrice.pending?.kind === "builder_part_group_create"
                              ? "Resume Group Create"
                              : pendingPrice.pending?.kind === "builder_part_group_dissolve"
                                ? "Resume Group Dissolve"
                                : pendingPrice.pending?.kind === "builder_blank_product_insert"
                                  ? "Resume Product Add"
                                  : pendingPrice.pending?.kind === "builder_product_remove"
                                    ? "Resume Product Remove"
                                    : pendingPrice.pending?.kind === "builder_quick_product_insert"
                                      ? pendingPrice.pending?.source_type === "product_clone" ? "Resume Product Clone" : "Resume Quick Product"
                                      : "Resume Price Update";
    throw new Error(`"${name}" has a Builder mutation recovery pending. Use ${resumeLabel} before converting this estimate to a Work Order.`);
  }
  if (estimateBefore.status !== "approved") {
    throw new Error("Only an Approved estimate can be converted to a Work Order. Record customer acceptance or approve the estimate first.");
  }
  if (estimateBefore.pipeline_sync_pending) {
    throw new Error("Sales Pipeline synchronization is still pending. Retry that synchronization from Finalize Estimate before converting this estimate to a Work Order.");
  }
  const anchor = expectedUpdatedDate === undefined ? estimate?.updated_date : expectedUpdatedDate;
  if (anchor && estimateBefore.updated_date && anchor !== estimateBefore.updated_date) {
    throw new Error("This estimate changed in another session. Reload before converting so newer approved pricing/details are not overwritten.");
  }

  let existing = null;
  if (sharedWorkOrder !== undefined) {
    // Combined path: the caller pre-resolved the canonical job (a create the
    // caller already committed, or a live WO one of the estimates links).
    existing = sharedWorkOrder;
  } else {
    const matches = await WorkOrder.filter({ estimate_id: estimate.id });
    const activeMatches = (matches || []).filter((row) => row?.deleted !== true);
    existing = selectExistingEstimateWorkOrder(activeMatches, estimateBefore.work_order_id || estimate.work_order_id);
    if (!existing && (matches || []).some((row) => row?.deleted === true)) {
      throw new Error("This estimate's linked Work Order is in Trash. Restore that Work Order from Project Trash before converting the estimate again.");
    }
    const linkedId = str(estimateBefore.work_order_id || estimate.work_order_id);
    if (!existing && linkedId) {
      // work_order_id is set but no estimate_id-linked WO matched — the link
      // may point at a WO created by the combined path (estimate_ids only).
      const linked = await WorkOrder.get(linkedId).catch(() => null);
      if (linked?.id && linked.deleted !== true) existing = linked;
    }
  }

  const customers = await loadAllCustomers();
  const resolvedCustomer = await resolveCustomerForEstimate(
    { ...estimateBefore, customer_id: existing?.customer_id || estimateBefore.customer_id || "" },
    customers || [],
  );
  const verifiedCustomerId = resolvedCustomer?.id || "";
  return { estimateBefore, existing, resolvedCustomer, verifiedCustomerId };
}

// Credit gate — CoreBridge semantics. `decide` resolves interactive prompts;
// without it the gate blocks non-admin holds/overages honestly (bulk path).
// Returns { outcome: "ok" } or { outcome: "blocked", reason } / "aborted".
export async function checkEstimateConversionCredit({
  resolvedCustomer,
  estimate,
  pricing = {},
  currentUser = null,
  sessionToken = "",
  decide = null,
} = {}) {
  if (!resolvedCustomer?.id) return { outcome: "ok" };
  const isAdmin = String(currentUser?.role || "").toLowerCase() === "admin";
  const customerName = resolvedCustomer?.company_name || "This customer";
  const decideOrBlock = async (kind, message) => {
    if (typeof decide === "function") {
      const answer = await decide({ kind, message, isAdmin });
      if (answer === "blocked") return { outcome: "blocked", reason: message };
      return answer ? { outcome: "ok" } : { outcome: "aborted", reason: message };
    }
    return isAdmin ? { outcome: "blocked", reason: `${message} (admin may override interactively)` } : { outcome: "blocked", reason: message };
  };
  if (resolvedCustomer?.credit_hold === true) {
    return decideOrBlock("credit_hold", `${customerName} is on CREDIT HOLD — new work orders are blocked. An administrator can clear the hold on the customer record.`);
  }
  if (Number(resolvedCustomer?.credit_limit) > 0) {
    const limit = Number(resolvedCustomer.credit_limit);
    const estimateTotal = Number.isFinite(num(pricing.quoteTotal, NaN))
      ? num(pricing.quoteTotal)
      : (estimate?.line_items || []).reduce(
          (sum, l) => sum + acceptedCustomerUnitPrice(l) * Math.max(1, Number(l?.customer_quantity) || 1),
          0,
        );
    let openAr = null;
    if (sessionToken) {
      try {
        const r = await base44.functions.invoke("invoicingAction", {
          session_token: sessionToken,
          action: "list_invoices",
          limit: 500,
        });
        const data = r?.data || r;
        if (data?.success) {
          openAr = (data.invoices || []).reduce(
            (sum, inv) => (inv?.customer_id === resolvedCustomer.id && inv?.status !== "void" ? sum + (Number(inv?.balance_due) || 0) : sum),
            0,
          );
        }
      } catch { /* openAr stays null — the block reason says it could not be verified */ }
    }
    const exposure = (openAr || 0) + estimateTotal;
    if (exposure > limit + 0.005) {
      const arNote = openAr == null ? "open AR could not be loaded" : `open AR ${openAr.toFixed(2)}`;
      return decideOrBlock("credit_limit", `${customerName} would exceed its credit limit — ${arNote} + this estimate ${estimateTotal.toFixed(2)} = ${exposure.toFixed(2)} vs limit ${limit.toFixed(2)}.`);
    }
  }
  return { outcome: "ok" };
}

// Write the WO (create or CAS-update), CAS-link the estimate, write the
// lifecycle revision. Returns { workOrder, estimateSaved }.
export async function commitEstimateConversion({
  estimate,
  estimateBefore,
  existing,
  verifiedCustomerId,
  pricing = {},
  sessionToken = "",
  entities = null,
  extraWorkOrderFields = {},
  idempotencyPrefix = "work_order_conversion",
  reason = "Converted approved estimate to Work Order",

} = {}) {
  const { Estimate, WorkOrder } = entities || defaultEntities();
  const src = estimateBefore || estimate;
  const sections = (src.line_items || [])
    .map((l) => `• ${getModuleLabel(l.module_key)} — ${l.project_name}`)
    .join("\n");

  const estimateProducts = buildEstimateWorkOrderProducts(src, pricing)
    .map((product) => ({
      ...product,
      source_estimate_id: src.id || "",
      source_estimate_number: src.estimate_number || "",
    }));
  const products = mergeWorkOrderProducts(existing?.products || [], estimateProducts);
  const generatedDescription = [src.notes, sections].filter(Boolean).join("\n\n");
  const materials = mergeWorkOrderMaterials(
    existing?.materials || [],
    await buildEstimateMaterialsManifest(src).catch(() => []),
  );
  const convertedFields = buildConvertedWorkOrderFields({
    estimate: src,
    pricing,
    existing,
    products,
    generatedDescription,
    conversionDate: localDateStamp(),
    verifiedCustomerId,
  });
  const hasConversionSalesActivity = !existing || hasVerifiedEstimateSalesActivity(existing, convertedFields, {
    includeProducts: true,
  });
  const conversionActivityStamp = new Date().toISOString();
  const workOrderFields = {
    ...convertedFields,
    materials,
    ...extraWorkOrderFields,
    ...(hasConversionSalesActivity ? { sales_last_activity_at: conversionActivityStamp } : {}),
    ...(existing?.sales_status !== "won" ? { sales_stage_changed_at: conversionActivityStamp } : {}),
  };

  let workOrder;
  if (existing?.id) {
    workOrder = await replaceWorkOrderFieldsIfUnchanged({
      workOrderId: existing.id,
      expectedFields: expectedWorkOrderFields(existing, workOrderFields),
      nextFields: workOrderFields,
      label: "Approved estimate Work Order conversion",
    });
  } else {
    const seedTasks = buildEstimateWorkOrderSeedTasks(src);
    const createFields = {
      ...workOrderFields,
      ...(seedTasks.length ? { tasks: seedTasks } : {}),
    };
    workOrder = await createEstimateLinkedWorkOrderWithRecovery({
      entity: WorkOrder,
      estimateId: src.id,
      data: createFields,
      label: "Approved estimate Work Order conversion",
      convergeCreated: (created) => convergeCreatedEstimateWorkOrder({
        estimateId: src.id,
        created,
        fields: createFields,
        sessionToken,
        duplicateLabel: "Work Order during simultaneous conversion",
      }),
    });
  }

  const internalCost = acceptedInternalEstimateCost(src.line_items || []);
  const { id: _id, created_date: _created_date, updated_date: _updated_date, created_by_id: _created_by_id, created_by: _created_by, ...estimateData } = src;
  const conversionEstimateFields = {
    ...estimateData,
    work_order_id: workOrder.id,
    status: "approved",
    edit_reason: "",
    total_cost: internalCost,
    quote_total: num(pricing.quoteTotal, num(src.quote_total)),
    sales_stage: "won",
    sales_stage_changed_at: new Date().toISOString(),
  };
  const estimateAfter = {
    ...src,
    ...conversionEstimateFields,
  };
  const estimateSaved = await replaceEstimateFieldsIfUnchanged({
    entity: Estimate,
    estimateId: src.id,
    expectedFields: expectedEstimateFields(src, conversionEstimateFields),
    guardFields: { updated_date: src.updated_date },
    nextFields: conversionEstimateFields,
    label: "Approved Estimate Work Order conversion link",
  });
  await ensureEstimateLifecycleRevision({
    idempotencyKey: `${idempotencyPrefix}:${workOrder.id}`,
    sessionToken,
    estimateBefore: src,
    estimateAfter,
    reason,
    revisionType: "conversion",
    quoteTotalBefore: src.quote_total,
    quoteTotalAfter: conversionEstimateFields.quote_total,
    internalCostBefore: src.total_cost,
    internalCostAfter: internalCost,
    workOrderId: workOrder.id,
  });
  return { workOrder, estimateSaved };
}

/**
 * Convert ONE approved estimate to a Work Order. Extracted from
 * ConvertToWorkOrder.jsx so the component and queue bulk actions share the
 * same guarded pipeline. UI hooks:
 *   hooks.confirmBeforeCommit(prepared) -> truthy to continue (preview gate)
 *   hooks.decideCredit({kind,message,isAdmin}) -> true to proceed, false to
 *     abort, "blocked" to record a hard block (omitted = non-interactive)
 */
export async function convertEstimateToWorkOrder({
  estimate,
  pricing = {},
  sessionToken = "",
  currentUser = null,
  expectedUpdatedDate = undefined,
  entities = null,
  hooks = {},
} = {}) {
  const prepared = await prepareEstimateConversion({ estimate, expectedUpdatedDate, entities });
  const credit = await checkEstimateConversionCredit({
    resolvedCustomer: prepared.resolvedCustomer,
    estimate: prepared.estimateBefore,
    pricing,
    currentUser,
    sessionToken,
    decide: hooks.decideCredit,
  });
  if (credit.outcome === "blocked") {
    return { status: "blocked", reason: credit.reason, prepared };
  }
  if (credit.outcome === "aborted") {
    return { status: "aborted", reason: credit.reason, prepared };
  }
  if (typeof hooks.confirmBeforeCommit === "function") {
    const proceed = await hooks.confirmBeforeCommit(prepared);
    if (!proceed) return { status: "aborted", prepared };
  }
  const result = await commitEstimateConversion({
    estimate,
    estimateBefore: prepared.estimateBefore,
    existing: prepared.existing,
    verifiedCustomerId: prepared.verifiedCustomerId,
    pricing,
    sessionToken,
    entities,
  });
  return { status: "converted", ...result };
}

/**
 * (#180) Combine multiple approved estimates into ONE canonical Work Order.
 * The earliest-created estimate keeps WO.estimate_id (single-link
 * compatibility); every estimate id lands in WO.estimate_ids and each
 * estimate's work_order_id links the shared job. Merged line_items (products
 * carry source_estimate_id provenance), tasks and materials are unioned onto
 * the WO. Each estimate transition is CAS-guarded on its own updated_date —
 * a concurrent edit aborts only that estimate's link, reported per row.
 */
export async function convertEstimatesToSharedWorkOrder({
  estimates = [],
  sessionToken = "",
  currentUser = null,
  entities = null,
  hooks = {},
} = {}) {
  const ent = entities || defaultEntities();
  const { WorkOrder } = ent;
  const rows = (Array.isArray(estimates) ? estimates : []).filter((e) => e && e.id);
  if (rows.length < 2) throw new Error("Select at least two approved estimates to combine into one Work Order.");

  // Load fresh rows and validate each up front — invalid estimates are
  // reported and excluded; conversion proceeds over the valid remainder.
  const prepared = [];
  const rejected = [];
  for (const row of rows) {
    try {
      prepared.push(await prepareEstimateConversion({ estimate: row, entities: ent, sharedWorkOrder: null }));
    } catch (error) {
      rejected.push({ estimate_id: row.id, estimate_number: row.estimate_number || "", reason: error?.message || "Not convertible." });
    }
  }
  if (prepared.length < 2) {
    return { status: "nothing_to_convert", rejected, results: [] };
  }
  prepared.sort((a, b) => str(a.estimateBefore?.created_date).localeCompare(str(b.estimateBefore?.created_date)) || str(a.estimateBefore?.id).localeCompare(str(b.estimateBefore?.id)));

  // Canonical job: a live WO any estimate already links wins (merge-into);
  // otherwise the WO gets created on the first commit below.
  const linkedIds = [...new Set(prepared.map((p) => str(p.estimateBefore?.work_order_id)).filter(Boolean))];
  let sharedWo = null;
  for (const woId of linkedIds) {
    const wo = await WorkOrder.get(woId).catch(() => null);
    if (wo?.id && wo.deleted !== true) { sharedWo = wo; break; }
    if (wo?.deleted === true) {
      rejected.push({ estimate_id: "", estimate_number: "", reason: `Linked Work Order ${woId} is in Trash — restore it before combining.` });
    }
  }
  if (linkedIds.length > 1) {
    const liveIds = [];
    for (const woId of linkedIds) {
      const wo = await WorkOrder.get(woId).catch(() => null);
      if (wo?.id && wo.deleted !== true) liveIds.push(woId);
    }
    if (liveIds.length > 1) {
      throw new Error(`These estimates already link to different Work Orders (${liveIds.length} live jobs). Unlink or convert them separately.`);
    }
  }

  // Credit gate on the combined exposure, resolved against the shared
  // customer (all estimates must name the same customer to combine — mixed
  // customers produce separate jobs, which this action is not for).
  const customerIds = new Set(prepared.map((p) => str(p.verifiedCustomerId)).filter(Boolean));
  if (customerIds.size > 1) {
    return { status: "mixed_customers", reason: "Selected estimates resolve to different customers — combined conversion requires one shared customer.", rejected, results: [] };
  }
  const combinedTotal = prepared.reduce((s, p) => s + estimateConvertedAmount(p.estimateBefore, {}), 0);
  const primary = prepared[0];
  const credit = await checkEstimateConversionCredit({
    resolvedCustomer: primary.resolvedCustomer,
    estimate: primary.estimateBefore,
    pricing: { quoteTotal: combinedTotal },
    currentUser,
    sessionToken,
    decide: hooks.decideCredit,
  });
  if (credit.outcome !== "ok") {
    return { status: credit.outcome, reason: credit.reason, rejected, results: [] };
  }

  const estimateIds = prepared.map((p) => str(p.estimateBefore?.id)).filter(Boolean);
  const estimateNumbers = prepared.map((p) => str(p.estimateBefore?.estimate_number || p.estimateBefore?.id));
  const results = [];
  let workOrder = sharedWo;
  const primaryEstimateId = str(primary.estimateBefore?.id);
  for (const p of prepared) {
    const src = p.estimateBefore;
    try {
      const committed = await commitEstimateConversion({
        estimate: src,
        estimateBefore: src,
        existing: workOrder,
        verifiedCustomerId: p.verifiedCustomerId,
        pricing: { quoteTotal: combinedTotal },
        sessionToken,
        entities: ent,
        extraWorkOrderFields: {
          estimate_ids: estimateIds,
          // WO.estimate_id stays on the EARLIEST-created estimate for
          // single-link compatibility; every id lands in estimate_ids.
          estimate_id: primaryEstimateId,
          // Combined-job estimate_amount is the FULL combined total — each
          // commit rewrites it to the same merged value.
          estimate_amount: combinedTotal,
          tasks: mergeWorkOrderTasks(
            workOrder?.tasks || [],
            buildEstimateWorkOrderSeedTasks(src, { idPrefix: `${str(src.id).slice(0, 8)}_` }),
          ),
        },
        idempotencyPrefix: `combined_work_order_conversion:${src.id}`,
        reason: `Combined ${prepared.length} approved estimates (${estimateNumbers.join(", ")}) into one Work Order`,
      });
      workOrder = committed.workOrder;
      results.push({ estimate_id: src.id, estimate_number: src.estimate_number || "", status: "linked", work_order_id: workOrder.id });
    } catch (error) {
      results.push({ estimate_id: src.id, estimate_number: src.estimate_number || "", status: "failed", reason: error?.message || "Conversion failed." });
    }
  }
  return { status: "converted", work_order_id: workOrder?.id || "", workOrder, results, rejected };
}

// D-10 — expandable products → parts detail model.
//
// Pure and IO-free: no React, no base44 client — esbuild-bundled and
// unit-tested under plain Node (scripts/test-products-to-parts.mjs).
//
// Where a product's constituent parts come from, in precedence order:
//   1. EMBEDDED SNAPSHOT — part rows stored on the product itself. WO
//      products[] rows are schemaless (additionalProperties) and several
//      pipelines embed a parts list: product.parts (canonical; array OR the
//      id-keyed map proofPipelineModel tolerates), part_list, builder_parts,
//      line_items, materials, components, and the builder_snapshot sub-lists
//      — the same candidate set workOrderConversion.resolveEstimateLineParts
//      scans for estimate lines. First non-empty list wins.
//   2. CATALOG — the caller-supplied partsCatalog (BuilderPart records,
//      the WO-level materials[] manifest from
//      estimateConversionService.buildEstimateMaterialsManifest, or a master
//      part catalog list). Rows are linked to the product by
//      builder_product_id / product_id / estimate_line_id / line_id.
//      Catalog also ENRICHES snapshot rows that lack a name or cost —
//      the row stays source:'snapshot' (that's where the quantity/identity
//      came from) and is flagged enriched:true.
//
// Money: storage fields are dollars (unit_cost / extended_cost /
// frozen_unit_cost / part_price...). Output rows are integer CENTS
// (unit_cost_cents / extended_cents) so expanded headers can sum without
// float drift. A genuinely absent cost stays null — the UI renders "—",
// never a fake $0.00; partsSummary.uncosted_parts counts them.
//
// Nothing in this module mutates its inputs — every returned row is a fresh
// object; productParts/expandableRows never write back into products[].

const clean = (v) => String(v ?? "").trim();
const isObj = (v) => v !== null && typeof v === "object" && !Array.isArray(v);
const num = (v, fallback = 0) => (Number.isFinite(Number(v)) ? Number(v) : fallback);
// First value that is actually present — 0 is a real cost, "" is not.
const firstPresent = (...vals) =>
  vals.find((v) => v !== undefined && v !== null && !(typeof v === "string" && v.trim() === ""));

// ---------------------------------------------------------------------------
// Part-type buckets — the expanded header's materials/labor/equipment/other
// rollup. part_type is an open string by schema design (BuilderPart.jsonc
// documents it that way); every value lands in exactly one bucket. Types
// observed from estimator partSync.makePart + the QuickProduct enum:
//   material · labor · equipment · service · fabrication · design_production ·
//   installation · permit · other (+ module subtypes in part_subtype).
// ---------------------------------------------------------------------------

export const PART_TYPE_BUCKETS = Object.freeze(["materials", "labor", "equipment", "other"]);

const BUCKET_BY_TYPE = {
  material: "materials",
  materials: "materials",
  fabrication: "materials", // fabricated subassembly = a produced physical part
  substrate: "materials",
  hardware: "materials",
  vinyl: "materials",
  lighting: "materials",
  supply: "materials",
  supplies: "materials",
  component: "materials",
  inventory: "materials",
  part: "materials",
  product: "materials",
  labor: "labor",
  design: "labor",
  design_production: "labor",
  artwork: "labor",
  service: "labor", // service lines (delivery, install services) are work, not stock
  installation: "labor",
  install: "labor",
  equipment: "equipment",
  machine: "equipment",
  rental: "equipment",
  crane: "equipment",
  permit: "other",
  other: "other",
};

export function bucketForPartType(partType) {
  return BUCKET_BY_TYPE[clean(partType).toLowerCase()] || "other";
}

// ---------------------------------------------------------------------------
// Embedded snapshot discovery
// ---------------------------------------------------------------------------

// Ordered candidate keys on the product itself; builder_snapshot is searched
// last (it's a whole-builder dump, least direct). First non-empty wins —
// mixed lists never merge, matching resolveEstimateLineParts semantics.
const TOP_LEVEL_LIST_KEYS = ["parts", "part_list", "builder_parts", "line_items", "materials", "components"];
const SNAPSHOT_LIST_KEYS = ["parts", "part_list", "builder_parts", "materials", "line_items"];

const listFrom = (value) => {
  if (Array.isArray(value)) return value.filter(isObj);
  // proofPipelineModel documents product.parts as also landing as an id-keyed
  // map; treat object values as the row list, keyed order preserved.
  if (isObj(value)) return Object.values(value).filter(isObj);
  return [];
};

// The product's embedded part rows + which field supplied them ("" = none).
export function embeddedPartList(product) {
  const p = isObj(product) ? product : {};
  for (const key of TOP_LEVEL_LIST_KEYS) {
    const rows = listFrom(p[key]);
    if (rows.length) return { rows, field: key };
  }
  const snap = isObj(p.builder_snapshot) ? p.builder_snapshot : {};
  for (const key of SNAPSHOT_LIST_KEYS) {
    const rows = listFrom(snap[key]);
    if (rows.length) return { rows, field: `builder_snapshot.${key}` };
  }
  return { rows: [], field: "" };
}

// ---------------------------------------------------------------------------
// Catalog — BuilderPart records, WO materials[] manifest rows, or master part
// catalog items. Accepts an array, a Map(id→row), or an id-keyed object.
// ---------------------------------------------------------------------------

// Every identity a part-ish row can carry, strongest first. The same keys are
// used to INDEX catalog rows and to LOOK UP snapshot refs, so matching works
// whichever spelling each side uses.
const REF_KEYS = ["part_id", "builder_part_id", "id", "part_key", "inventory_item_id", "line_id"];

const rowRefs = (row = {}) => REF_KEYS.map((k) => clean(row?.[k])).filter(Boolean);

export function catalogRows(catalog) {
  if (!catalog) return [];
  if (catalog instanceof Map) return [...catalog.values()].filter(isObj);
  if (Array.isArray(catalog)) return catalog.filter(isObj);
  if (isObj(catalog)) return Object.values(catalog).filter(isObj);
  return [];
}

// key → catalog row. First writer wins so duplicate-keyed catalogs stay stable.
function catalogIndex(catalog) {
  const index = new Map();
  for (const row of catalogRows(catalog)) {
    for (const ref of rowRefs(row)) {
      if (!index.has(ref)) index.set(ref, row);
    }
  }
  return index;
}

const matchCatalog = (index, row) => {
  for (const ref of rowRefs(row)) {
    const hit = index.get(ref);
    if (hit) return hit;
  }
  return null;
};

// ---------------------------------------------------------------------------
// Field extraction — every spelling seen across BuilderPart, the WO materials
// manifest, embedded partSync parts, QuickProduct parts, and line-ish rows.
// ---------------------------------------------------------------------------

const nameOf = (r = {}) =>
  clean(firstPresent(
    r.part_name, r.name, r.client_label, r.item_label, r.part_label,
    r.inventory_item_name, r.material_name, r.service_name, r.description,
    r.part_key,
  ));

const typeOf = (r = {}) => clean(firstPresent(r.part_type, r.type, r.item_type, r.kind));
const subtypeOf = (r = {}) => clean(firstPresent(r.part_subtype, r.subtype));
const unitOf = (r = {}) => clean(firstPresent(r.unit, r.uom, r.pricing_mode));
const qtyOf = (r = {}) => num(firstPresent(r.quantity, r.part_qty, r.qty, r.count), 1);

// Integer cents when the row already speaks cents; null when absent.
const centsDirect = (r, keys) => {
  for (const k of keys) {
    const v = r?.[k];
    if (Number.isFinite(Number(v))) return Math.round(Number(v));
  }
  return null;
};

// Dollars → integer cents; null when absent so "unknown" never renders as $0.
const centsFromDollars = (v) =>
  (Number.isFinite(Number(v)) ? Math.round(Number(v) * 100) : null);

// A BuilderPart manual_cost is authoritative only while manual_cost_override
// is set; frozen_* is the customer-approved snapshot and outranks current_*.
const unitDollars = (r = {}) => {
  const manual = r.manual_cost_override === true ? r.manual_cost : undefined;
  return firstPresent(
    manual,
    r.unit_cost, r.unitCost, r.frozen_unit_cost, r.current_unit_cost,
    r.unit_price, r.cost_per_unit, r.default_rate, r.price, r.manual_cost,
  );
};

const extendedDollars = (r = {}) => {
  const explicit = firstPresent(
    r.price_override, // QuickProduct: replaces the whole line total
    r.extended_cost, r.ext_cost, r.extCost,
    r.frozen_extended_cost, r.current_extended_cost,
    r.total_cost, r.line_total, r.total,
  );
  if (explicit !== undefined) return explicit;
  // QuickProduct part rows: line total = part_price + modifier_price.
  if (Number.isFinite(Number(r.part_price)) || Number.isFinite(Number(r.modifier_price))) {
    return num(r.part_price) + num(r.modifier_price);
  }
  return undefined;
};

const unitCents = (r = {}) =>
  centsDirect(r, ["unit_cost_cents", "unitCostCents", "cost_cents"]) ?? centsFromDollars(unitDollars(r));

const extendedCents = (r = {}) =>
  centsDirect(r, ["extended_cents", "ext_cost_cents", "extendedCostCents", "total_cost_cents"]) ??
  centsFromDollars(extendedDollars(r));

// Normalize any part-ish storage row into the render row. `source` is set by
// the caller ('snapshot' | 'catalog'); never mutates `raw`.
function normalizePartRow(raw, source) {
  const r = isObj(raw) ? raw : {};
  const quantity = qtyOf(r);
  let unit_cost_cents = unitCents(r);
  let extended_cents = extendedCents(r);
  // Derive the missing leg arithmetically — display math, not data invention.
  if (extended_cents == null && unit_cost_cents != null) {
    extended_cents = Math.round(unit_cost_cents * quantity);
  }
  if (unit_cost_cents == null && extended_cents != null && quantity > 0) {
    unit_cost_cents = Math.round(extended_cents / quantity);
  }
  const part_type = typeOf(r);
  return {
    part_id: clean(firstPresent(r.part_id, r.builder_part_id, r.id, r.part_key, r.inventory_item_id, r.line_id)),
    part_key: clean(r.part_key),
    name: nameOf(r),
    part_type,
    part_subtype: subtypeOf(r),
    type_bucket: bucketForPartType(part_type),
    quantity,
    unit: unitOf(r),
    unit_cost_cents,
    extended_cents,
    source,
    enriched: false,
    enriched_fields: [],
  };
}

// Fill missing name/cost legs on a snapshot row from its catalog match.
// Returns the same normalized row object with enriched flags — the snapshot
// remains the source of truth for identity + quantity.
function enrichFromCatalog(row, catalogRow) {
  if (!catalogRow) return row;
  const filled = [];
  const cat = normalizePartRow(catalogRow, "catalog");
  if (!row.name && cat.name) { row.name = cat.name; filled.push("name"); }
  if (row.unit_cost_cents == null && cat.unit_cost_cents != null) {
    row.unit_cost_cents = cat.unit_cost_cents; filled.push("unit_cost_cents");
  }
  if (row.extended_cents == null && cat.extended_cents != null) {
    row.extended_cents = cat.extended_cents; filled.push("extended_cents");
  }
  // A catalog-extended fill lets the unit leg derive honestly too.
  if (row.unit_cost_cents == null && row.extended_cents != null && row.quantity > 0) {
    row.unit_cost_cents = Math.round(row.extended_cents / row.quantity);
    filled.push("unit_cost_cents");
  }
  if (row.extended_cents == null && row.unit_cost_cents != null) {
    row.extended_cents = Math.round(row.unit_cost_cents * row.quantity);
    filled.push("extended_cents");
  }
  if (filled.length) {
    row.enriched = true;
    row.enriched_fields = [...new Set(filled)];
  }
  return row;
}

// Catalog rows linked to one product — the no-embedded-snapshot fallback.
// Link keys cover BuilderPart (builder_product_id / estimate_line_id), the WO
// materials manifest (same), and ad-hoc catalogs (product_id / line_id).
function catalogRowsForProduct(product, catalog) {
  const p = isObj(product) ? product : {};
  const bp = clean(p.builder_product_id);
  const line = clean(p.estimate_line_id);
  const pid = clean(firstPresent(p.id, p.product_id));
  if (!bp && !line && !pid) return [];
  const seen = new Set();
  return catalogRows(catalog).filter((row) => {
    if (row.is_active === false || row.deleted === true) return false;
    const rowId = clean(row.id);
    // WO product.id is often itself the builder_product_id or estimate line_id
    // (buildEstimateWorkOrderProducts seeds id that way), so a catalog row's
    // product/line keys are matched against all three product identities.
    const linked =
      (bp && clean(row.builder_product_id) === bp) ||
      (line && (clean(row.estimate_line_id) === line || clean(row.line_id) === line)) ||
      (pid && (
        clean(row.product_id) === pid || clean(row.work_order_product_id) === pid ||
        clean(row.builder_product_id) === pid ||
        clean(row.estimate_line_id) === pid || clean(row.line_id) === pid
      ));
    if (!linked) return false;
    const dedupe = rowId || `${clean(row.part_key)}|${nameOf(row)}`;
    if (seen.has(dedupe)) return false;
    seen.add(dedupe);
    return true;
  });
}

// ---------------------------------------------------------------------------
// productParts — the product's constituent part rows for the expanded detail.
// ---------------------------------------------------------------------------

// productParts(product, { partsCatalog }) →
//   [{ part_id, part_key, name, part_type, part_subtype, type_bucket,
//      quantity, unit, unit_cost_cents, extended_cents,
//      source:'snapshot'|'catalog', enriched, enriched_fields }]
//
// Embedded snapshots win (source:'snapshot'); when the product carries no
// embedded list, catalog rows linked by builder_product_id / estimate_line_id
// / product id resolve with source:'catalog'. Snapshot rows missing a name or
// cost are enriched from their catalog match (enriched:true) — the row still
// reports source:'snapshot'. Inactive/deleted rows are dropped on both paths.
export function productParts(product, { partsCatalog } = {}) {
  if (!isObj(product)) return [];
  const index = catalogIndex(partsCatalog);
  const { rows: embedded } = embeddedPartList(product);

  if (embedded.length) {
    return embedded
      .filter((r) => r.is_active !== false && r.deleted !== true)
      .map((r) => {
        const row = normalizePartRow(r, "snapshot");
        const hit = index.size ? matchCatalog(index, r) : null;
        return hit ? enrichFromCatalog(row, hit) : row;
      });
  }

  return catalogRowsForProduct(product, partsCatalog)
    .map((r) => normalizePartRow(r, "catalog"));
}

// ---------------------------------------------------------------------------
// partsSummary — header rollup for the expanded row.
// ---------------------------------------------------------------------------

// partsSummary(product, parts) →
//   { total_parts, total_quantity, total_cost_cents, uncosted_parts,
//     by_type: { materials:{count,cost_cents}, labor:{…}, equipment:{…}, other:{…} } }
//
// `parts` may be productParts output (used verbatim) or raw storage rows
// (normalized on the fly); omit it to resolve from the product itself.
export function partsSummary(product, parts) {
  const list = Array.isArray(parts)
    ? parts.map((r) => ("type_bucket" in (r || {}) || "extended_cents" in (r || {}) ? r : normalizePartRow(r, "snapshot")))
    : productParts(product);
  const by_type = {
    materials: { count: 0, cost_cents: 0 },
    labor: { count: 0, cost_cents: 0 },
    equipment: { count: 0, cost_cents: 0 },
    other: { count: 0, cost_cents: 0 },
  };
  let total_cost_cents = 0;
  let total_quantity = 0;
  let uncosted_parts = 0;
  for (const part of list) {
    const bucket = PART_TYPE_BUCKETS.includes(part?.type_bucket) ? part.type_bucket : "other";
    const cost = Number.isFinite(part?.extended_cents) ? part.extended_cents : 0;
    by_type[bucket].count += 1;
    by_type[bucket].cost_cents += cost;
    total_cost_cents += cost;
    total_quantity += num(part?.quantity);
    if (!Number.isFinite(part?.extended_cents) && !Number.isFinite(part?.unit_cost_cents)) uncosted_parts += 1;
  }
  return {
    total_parts: list.length,
    total_quantity,
    total_cost_cents,
    uncosted_parts,
    by_type,
  };
}

// ---------------------------------------------------------------------------
// expandableRows — flattened render list honoring an expanded_ids set.
// ---------------------------------------------------------------------------

// Product row identity: explicit id first, then the product's stable links —
// mirrors workspaceProductRows' synthetic `${wo.id}-${idx}` tail.
export function productRowId(product, index = 0, workOrderId = "") {
  const p = isObj(product) ? product : {};
  return clean(firstPresent(p.id, p.product_id, p.builder_product_id, p.estimate_line_id)) ||
    `${clean(workOrderId) ? `${clean(workOrderId)}-` : "product-"}${index}`;
}

const expandedHas = (expandedIds, id) => {
  if (expandedIds === true || expandedIds === "*") return true;
  if (!expandedIds) return false;
  if (expandedIds instanceof Set) return expandedIds.has(id);
  if (Array.isArray(expandedIds)) return expandedIds.includes(id);
  if (isObj(expandedIds)) return expandedIds[id] === true || id in expandedIds;
  return false;
};

// expandableRows(products, { expanded_ids, partsCatalog, work_order_id }) →
//   flat list for a table/accordion render:
//     { type:'product', product_id, index, expanded, product, summary, parts }
//     { type:'part', parent_product_id, product_id, index, part_index, part }
// Part rows follow their product row only while product_id ∈ expanded_ids.
// `expanded_ids` accepts a Set, an array, an id-keyed map, or true/'*' for
// expand-all. summary is always computed — the collapsed header needs the
// parts count and cost rollup.
export function expandableRows(products, opts = {}) {
  const list = Array.isArray(products) ? products : [];
  const { expanded_ids, partsCatalog, work_order_id } = opts || {};
  const out = [];
  list.forEach((product, index) => {
    if (!isObj(product)) return;
    const product_id = productRowId(product, index, work_order_id);
    const parts = productParts(product, { partsCatalog });
    const expanded = expandedHas(expanded_ids, product_id);
    out.push({
      type: "product",
      product_id,
      index,
      expanded,
      product,
      summary: partsSummary(product, parts),
      parts,
    });
    if (!expanded) return;
    parts.forEach((part, part_index) => {
      out.push({
        type: "part",
        parent_product_id: product_id,
        product_id,
        index,
        part_index,
        part,
      });
    });
  });
  return out;
}

// ---------------------------------------------------------------------------
// missingPartRefs — data-quality flag: part refs the product carries that the
// catalog cannot resolve.
// ---------------------------------------------------------------------------

// missingPartRefs(product, catalog) →
//   [{ ref, part_id, part_key, name, field }]
// Every identity carried by an embedded part row (or the scalar ref arrays
// part_ids / builder_part_ids / part_refs / part_list_ids) that no catalog row
// answers. Rows with no identifier can't dangle and are skipped. An empty/
// absent catalog flags every ref — the honest answer when no catalog loaded.
export function missingPartRefs(product, catalog) {
  if (!isObj(product)) return [];
  const index = catalogIndex(catalog);
  const out = [];
  const seen = new Set();
  const flag = (ref, row = {}, field = "") => {
    const key = clean(ref);
    if (!key || seen.has(key)) return;
    seen.add(key);
    out.push({
      ref: key,
      part_id: clean(firstPresent(row.part_id, row.builder_part_id, row.id)),
      part_key: clean(row.part_key),
      name: nameOf(row),
      field: field || "parts",
    });
  };

  const { rows, field } = embeddedPartList(product);
  for (const row of rows) {
    const refs = rowRefs(row);
    if (!refs.length) continue; // self-contained snapshot row, not a ref
    if (!refs.some((ref) => index.has(ref))) flag(refs[0], row, field);
  }

  for (const key of ["part_ids", "builder_part_ids", "part_refs", "part_list_ids"]) {
    const raw = product[key];
    const vals = Array.isArray(raw) ? raw : raw == null ? [] : [raw];
    for (const v of vals) {
      const ref = isObj(v) ? clean(firstPresent(v.part_id, v.builder_part_id, v.id, v.part_key)) : clean(v);
      if (ref && !index.has(ref)) flag(ref, isObj(v) ? v : {}, key);
    }
  }
  return out;
}
